void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    float numBars = 64.0;

    float barIndex = floor(uv.x * numBars);
    float inBarX = fract(uv.x * numBars);

    float gapSize = 0.4; 

    if (inBarX > (1.0 - gapSize)) {
        fragColor = vec4(0.0);
        return;
    }

    float audioValue = texture(iChannel1, vec2(barIndex / numBars, 0.0)).x;

    audioValue = audioValue - 0.25;           // create a new baseline to be at 0 uv.y 
                                              // ( the audio input is not 0 when there is no sound so we subtract a bit to make it look better)
    audioValue = max(audioValue, 0.0);

    float barHeight = audioValue * 1.5;  // sensitivity
    float glowRange = 0.04;              // how tall the “glow” extends above the bar

    if (uv.y > barHeight + glowRange)
    {
        fragColor = vec4(0.0);          // background color 
        return;
    }

    float factor = clamp((uv.y - 0.2) / (1.0 - 0.6), 0.0, 1.0);

    vec3 colorBottom = vec3(0.6, 1.0, 0.1);  
    vec3 colorTop    = vec3(1.0, 0.0, 0.0);  
    vec3 barColor    = mix(colorBottom, colorTop, factor);

    if (uv.y <= barHeight) 
    {
        fragColor = vec4(barColor, 1.0);
    }
    else 
    {
        float distAbove = uv.y - barHeight;

        float glowFrac = 1.0 - clamp(distAbove / glowRange, 0.0, 1.0 );

        float topFactor = clamp((barHeight - 0.2) / (1.0 - 0.6), 0.0, 1.0);
        vec3  topOfBarColor = mix(colorBottom, colorTop, topFactor);

        float glowIntensity = 0.75;

        vec3 glowColor = topOfBarColor * glowIntensity * glowFrac;

        fragColor = vec4(glowColor, 1.0);
    }
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord / iResolution.xy;

    float rawVal = texture(iChannel0, uv).x;

    float oldVal = texture(iChannel1, uv).x;

    float alpha = 0.6; // closer to 1 = slower, smoother changes
    float newVal = mix(rawVal, oldVal, alpha);

    fragColor = vec4(newVal, 0.0, 0.0, 1.0);
}
